-- Honduras, El Salvador y Nicaragua · colección regional inicial.
-- Las fichas se pueden enriquecer desde Administración; las fuentes quedan
-- guardadas para mantener trazabilidad editorial.
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, country=EXCLUDED.country, country_code=EXCLUDED.country_code, department=EXCLUDED.department, category=EXCLUDED.category, description=EXCLUDED.description, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, activities=EXCLUDED.activities, cost_currency=EXCLUDED.cost_currency, points=EXCLUDED.points, source_url=EXCLUDED.source_url, metadata=EXCLUDED.metadata, updated_at=now();

SELECT id, 'NMD-' || country_code || '-' || upper(left(replace(slug,'-','_'),28)), 'Sello · ' || name, 'Sello de exploración Nómada para ' || name, CASE country_code WHEN 'HN' THEN '#1F769A' WHEN 'SV' THEN '#405DAD' ELSE '#4A997C' END, true
FROM destinations WHERE country_code IN ('HN','SV','NI')
ON CONFLICT (destination_id) DO NOTHING;
